protected IAIState findStable() {
    IColony colony = this.worker.getCitizenColonyHandler().getColonyOrRegister();
    if (this.stablePos == null) {
        this.stablePos = colony.getServerBuildingManager().getBestBuilding(this.worker.m_20183_(), BuildingStable.class);
    }
