import com.minecolonies.core.colony.buildings.AbstractBuildingGuards;
import com.minecolonies.core.colony.jobs.guard.JobHuscarl;
import com.minecolonies.core.colony.jobs.guard.JobKnight;
import com.minecolonies.core.entity.ai.workers.guard.AbstractEntityAIGuard;
import com.minecolonies.core.entity.ai.workers.guard.MeleeCombatAI;
import com.minecolonies.core.entity.citizen.EntityCitizen;
import java.util.List;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.item.Items;
import org.jetbrains.annotations.NotNull;

public class EntityAIMelee
extends AbstractEntityAIGuard<JobKnight, AbstractBuildingGuards> {
    public EntityAIMelee(@NotNull JobKnight job) {
        super(job);
        super.registerTargets(new TickingTransition[0]);
        if (job instanceof JobHuscarl) {
            this.toolsNeeded.add((EquipmentTypeEntry)ModEquipmentTypes.axe.get());
        } else {
            this.toolsNeeded.add((EquipmentTypeEntry)ModEquipmentTypes.sword.get());
        }
        for (List list : this.itemsNeeded) {
            list.add(new GuardGear((EquipmentTypeEntry)ModEquipmentTypes.shield.get(), EquipmentSlot.OFFHAND, 0, Integer.MAX_VALUE, GuardConstants.SHIELD_LEVEL_RANGE, GuardConstants.SHIELD_BUILDING_LEVEL_RANGE));
        }
        new MeleeCombatAI((EntityCitizen)this.worker, this.getStateAI(), this);
    }

    @Override
    @NotNull
    protected List<ItemStorage> itemsNiceToHave() {
        List<ItemStorage> list = super.itemsNiceToHave();
        if (this.worker.getCitizenColonyHandler().getColonyOrRegister().getResearchManager().getResearchEffects().getEffectStrength(ResearchConstants.SHIELD_USAGE) > 0.0) {
            list.add(new ItemStorage(Items.f_42740_, 1));
        }
        return list;
    }
}

